public int[][] floodFill(int[][] image, int sr, int sc, int newColor) {
    int color = image[sr][sc];
    if (color != newColor) dfs(image, sr, sc, color, newColor);
    return image;
}
private void dfs(int[][] img, int r, int c, int color, int newColor) {
    if (r < 0 || r >= img.length || c < 0 || c >= img[0].length || img[r][c] != color) return;
    img[r][c] = newColor;
    dfs(img, r+1, c, color, newColor);
    dfs(img, r-1, c, color, newColor);
    dfs(img, r, c+1, color, newColor);
    dfs(img, r, c-1, color, newColor);
}

