function floydWarshall(V, graph) {
  const dist = Array.from({ length: V }, (_, i) => 
    Array.from({ length: V }, (_, j) => i === j ? 0 : (graph[i]?.[j] ?? Infinity))
  );
  for (let k = 0; k < V; k++) {
    for (let i = 0; i < V; i++) {
      for (let j = 0; j < V; j++) {
        if (dist[i][k] + dist[k][j] < dist[i][j]) {
          dist[i][j] = dist[i][k] + dist[k][j];
        }
      }
    }
  }
  return dist;
}

