function kosaraju(V, adj) {
  const visited = new Set(), stack = [], sccs = [];
  function dfs1(u) {
    visited.add(u);
    for (const v of adj[u] || []) if (!visited.has(v)) dfs1(v);
    stack.push(u);
  }
  for (let i = 0; i < V; i++) if (!visited.has(i)) dfs1(i);
  const transpose = Array.from({ length: V }, () => []);
  for (let u = 0; u < V; u++) {
    for (const v of adj[u] || []) transpose[v].push(u);
  }
  visited.clear();
  function dfs2(u, currSCC) {
    visited.add(u); currSCC.push(u);
    for (const v of transpose[u] || []) if (!visited.has(v)) dfs2(v, currSCC);
  }
  while (stack.length) {
    const u = stack.pop();
    if (!visited.has(u)) { const curr = []; dfs2(u, curr); sccs.push(curr); }
  }
  return sccs;
}

code.python:
def kosaraju(V, adj):
    visited, stack, sccs = set(), [], []
    def dfs1(u):
        visited.add(u)
        for v in adj[u]:
            if v not in visited: dfs1(v)
        stack.append(u)
    for i in range(V):
        if i not in visited: dfs1(i)
    transpose = [[] for _ in range(V)]
    for u in range(V):
        for v in adj[u]: transpose[v].append(u)
    visited.clear()
    def dfs2(u, curr):
        visited.add(u); curr.append(u)
        for v in transpose[u]:
            if v not in visited: dfs2(v, curr)
    while stack:
        u = stack.pop()
        if u not in visited:
            curr = []
            dfs2(u, curr)
            sccs.append(curr)
    return sccs

