public List<List<Integer>> kosaraju(int V, List<List<Integer>> adj) {
    List<Integer> stack = new ArrayList<>();
    boolean[] visited = new boolean[V];
    for (int i = 0; i < V; i++) if (!visited[i]) dfs1(i, adj, visited, stack);
    List<List<Integer>> transpose = new ArrayList<>();
    for (int i = 0; i < V; i++) transpose.add(new ArrayList<>());
    for (int u = 0; u < V; u++) for (int v : adj.get(u)) transpose.get(v).add(u);
    Arrays.fill(visited, false);
    List<List<Integer>> sccs = new ArrayList<>();
    for (int i = stack.size() - 1; i >= 0; i--) {
        int u = stack.get(i);
        if (!visited[u]) { List<Integer> curr = new ArrayList<>(); dfs2(u, transpose, visited, curr); sccs.add(curr); }
    }
    return sccs;
}
private void dfs1(int u, List<List<Integer>> adj, boolean[] vis, List<Integer> stack) {
    vis[u] = true;
    for (int v : adj.get(u)) if (!vis[v]) dfs1(v, adj, vis, stack);
    stack.add(u);
}
private void dfs2(int u, List<List<Integer>> adjT, boolean[] vis, List<Integer> curr) {
    vis[u] = true; curr.add(u);
    for (int v : adjT.get(u)) if (!vis[v]) dfs2(v, adjT, vis, curr);
}

code.cpp:
vector<vector<int>> kosaraju(int V, vector<vector<int>>& adj) {
    vector<int> stack; vector<bool> vis(V, false);
    auto dfs1 = [&](auto self, int u) -> void {
        vis[u] = true;
        for (int v : adj[u]) if (!vis[v]) self(self, v);
        stack.push_back(u);
    };
    for (int i = 0; i < V; i++) if (!vis[i]) dfs1(dfs1, i);
    vector<vector<int>> adjT(V);
    for (int u = 0; u < V; u++) for (int v : adj[u]) adjT[v].push_back(u);
    fill(vis.begin(), vis.end(), false);
    vector<vector<int>> sccs;
    auto dfs2 = [&](auto self, int u, vector<int>& curr) -> void {
        vis[u] = true; curr.push_back(u);
        for (int v : adjT[u]) if (!vis[v]) self(self, v, curr);
    };
    reverse(stack.begin(), stack.end());
    for (int u : stack) {
        if (!vis[u]) { vector<int> curr; dfs2(dfs2, u, curr); sccs.push_back(curr); }
    }
    return sccs;
}

