function findBridges(n, connections) {
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v] of connections) { adj[u].push(v); adj[v].push(u); }
  const tin = Array(n).fill(-1), low = Array(n).fill(-1);
  const bridges = [];
  let timer = 0;
  function dfs(u, parent = -1) {
    tin[u] = low[u] = timer++;
    for (const v of adj[u]) {
      if (v === parent) continue;
      if (tin[v] !== -1) low[u] = Math.min(low[u], tin[v]);
      else {
        dfs(v, u);
        low[u] = Math.min(low[u], low[v]);
        if (low[v] > tin[u]) bridges.push([u, v]);
      }
    }
  }
  dfs(0);
  return bridges;
}

code.python:
def findBridges(n, connections):
    adj = [[] for _ in range(n)]
    for u, v in connections: adj[u].append(v); adj[v].append(u)
    tin, low = [-1]*n, [-1]*n
    bridges, timer = [], 0
    def dfs(u, p=-1):
        nonlocal timer
        tin[u] = low[u] = timer; timer += 1
        for v in adj[u]:
            if v == p: continue
            if tin[v] != -1: low[u] = min(low[u], tin[v])
            else:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > tin[u]: bridges.append([u, v])
    dfs(0)
    return bridges

