public List<List<Integer>> findBridges(int n, List<List<Integer>> connections) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
    for (List<Integer> c : connections) { adj.get(c.get(0)).add(c.get(1)); adj.get(c.get(1)).add(c.get(0)); }
    int[] tin = new int[n], low = new int[n];
    Arrays.fill(tin, -1); Arrays.fill(low, -1);
    List<List<Integer>> bridges = new ArrayList<>();
    dfs(0, -1, 0, adj, tin, low, bridges);
    return bridges;
}
private void dfs(int u, int p, int timer, List<List<Integer>> adj, int[] tin, int[] low, List<List<Integer>> bridges) {
    tin[u] = low[u] = timer++;
    for (int v : adj.get(u)) {
        if (v == p) continue;
        if (tin[v] != -1) low[u] = Math.min(low[u], tin[v]);
        else {
            dfs(v, u, timer, adj, tin, low, bridges);
            low[u] = Math.min(low[u], low[v]);
            if (low[v] > tin[u]) bridges.add(Arrays.asList(u, v));
        }
    }
}

