vector<vector<int>> findBridges(int n, vector<vector<int>>& connections) {
    vector<vector<int>> adj(n);
    for (auto& c : connections) { adj[c[0]].push_back(c[1]); adj[c[1]].push_back(c[0]); }
    vector<int> tin(n, -1), low(n, -1);
    vector<vector<int>> bridges; int timer = 0;
    auto dfs = [&](auto self, int u, int p = -1) -> void {
        tin[u] = low[u] = timer++;
        for (int v : adj[u]) {
            if (v == p) continue;
            if (tin[v] != -1) low[u] = min(low[u], tin[v]);
            else {
                self(self, v, u);
                low[u] = min(low[u], low[v]);
                if (low[v] > tin[u]) bridges.push_back({u, v});
            }
        }
    };
    dfs(dfs, 0);
    return bridges;
}

