function isBipartite(graph) {
  const n = graph.length;
  const colors = Array(n).fill(0); // 0: uncolored, 1: Red, -1: Blue
  for (let i = 0; i < n; i++) {
    if (colors[i] !== 0) continue;
    const queue = [i]; colors[i] = 1;
    while (queue.length) {
      const u = queue.shift();
      for (const v of graph[u]) {
        if (colors[v] === colors[u]) return false;
        if (colors[v] === 0) { colors[v] = -colors[u]; queue.push(v); }
      }
    }
  }
  return true;
}

