    colors = [0] * n
    for i in range(n):
        if colors[i] != 0: continue
        queue = [i]; colors[i] = 1
        while queue:
            u = queue.pop(0)
            for v in graph[u]:
                if colors[v] == colors[u]: return False
                if colors[v] == 0:
                    colors[v] = -colors[u]
                    queue.append(v)
