public boolean isBipartite(int[][] graph) {
    int n = graph.length;
    int[] colors = new int[n];
    for (int i = 0; i < n; i++) {
        if (colors[i] != 0) continue;
        Queue<Integer> q = new LinkedList<>();
        q.add(i); colors[i] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : graph[u]) {
                if (colors[v] == colors[u]) return false;
                if (colors[v] == 0) { colors[v] = -colors[u]; q.add(v); }
            }
        }
    }
    return true;
}

