function edmondsKarp(capacity, source, sink) {
  const n = capacity.length;
  const flow = Array.from({ length: n }, () => Array(n).fill(0));
  let maxFlow = 0;
  while (true) {
    const parent = Array(n).fill(-1);
    const queue = [source]; parent[source] = source;
    while (queue.length && parent[sink] === -1) {
      const u = queue.shift();
      for (let v = 0; v < n; v++) {
        if (parent[v] === -1 && capacity[u][v] - flow[u][v] > 0) {
          parent[v] = u; queue.push(v);
        }
      }
    }
    if (parent[sink] === -1) break;
    let pathFlow = Infinity;
    for (let v = sink; v !== source; v = parent[v]) {
      const u = parent[v]; pathFlow = Math.min(pathFlow, capacity[u][v] - flow[u][v]);
    }
    for (let v = sink; v !== source; v = parent[v]) {
      const u = parent[v]; flow[u][v] += pathFlow; flow[v][u] -= pathFlow;
    }
    maxFlow += pathFlow;
  }
  return maxFlow;
}

code.python:
def edmondsKarp(capacity, source, sink):
    n = len(capacity)
    flow = [[0]*n for _ in range(n)]
    max_flow = 0
    while True:
        parent = [-1]*n
        queue = [source]; parent[source] = source
        while queue and parent[sink] == -1:
            u = queue.pop(0)
            for v in range(n):
                if parent[v] == -1 and capacity[u][v] - flow[u][v] > 0:
                    parent[v] = u; queue.append(v)
        if parent[sink] == -1: break
        path_flow = float('inf')
        v = sink
        while v != source:
            u = parent[v]; path_flow = min(path_flow, capacity[u][v] - flow[u][v]); v = parent[v]
        v = sink
        while v != source:
            u = parent[v]; flow[u][v] += path_flow; flow[v][u] -= path_flow; v = parent[v]
        max_flow += path_flow
    return max_flow

code.java:
public int edmondsKarp(int[][] capacity, int source, int sink) {
    int n = capacity.length, maxFlow = 0;
    int[][] flow = new int[n][n];
    while (true) {
        int[] parent = new int[n]; Arrays.fill(parent, -1);
        Queue<Integer> q = new LinkedList<>();
        q.add(source); parent[source] = source;
        while (!q.isEmpty() && parent[sink] == -1) {
            int u = q.poll();
            for (int v = 0; v < n; v++) {
                if (parent[v] == -1 && capacity[u][v] - flow[u][v] > 0) {
                    parent[v] = u; q.add(v);
                }
            }
        }
        if (parent[sink] == -1) break;
        int pathFlow = Integer.MAX_VALUE;
        for (int v = sink; v != source; v = parent[v]) {
            pathFlow = Math.min(pathFlow, capacity[parent[v]][v] - flow[parent[v]][v]);
        }
        for (int v = sink; v != source; v = parent[v]) {
            flow[parent[v]][v] += pathFlow; flow[v][parent[v]] -= pathFlow;
        }
        maxFlow += pathFlow;
    }
    return maxFlow;
}

