function findPath(maze, n) {
  const paths = [], visited = Array.from({length: n}, () => Array(n).fill(false));
  function dfs(r, c, path) {
    if (r === n - 1 && c === n - 1) { paths.push(path); return; }
    const dirs = [['D', 1, 0], ['L', 0, -1], ['R', 0, 1], ['U', -1, 0]];
    visited[r][c] = true;
    for (const [dir, dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr >= 0 && nr < n && nc >= 0 && nc < n && !visited[nr][nc] && maze[nr][nc] === 1) {
        dfs(nr, nc, path + dir);
      }
    }
    visited[r][c] = false;
  }
  if (maze[0][0] === 1) dfs(0, 0, '');
  return paths;
}

