public List<String> findPath(int[][] maze, int n) {
    List<String> paths = new ArrayList<>();
    boolean[][] visited = new boolean[n][n];
    if (maze[0][0] == 1) dfs(0, 0, "", maze, n, visited, paths);
    return paths;
}
private void dfs(int r, int c, String path, int[][] maze, int n, boolean[][] visited, List<String> paths) {
    if (r == n - 1 && c == n - 1) { paths.add(path); return; }
    visited[r][c] = true;
    int[] dr = {1, 0, 0, -1}, dc = {0, -1, 1, 0};
    char[] dirNames = {'D', 'L', 'R', 'U'};
    for (int i = 0; i < 4; i++) {
        int nr = r + dr[i], nc = c + dc[i];
        if (nr >= 0 && nr < n && nc >= 0 && nc < n && !visited[nr][nc] && maze[nr][nc] == 1) {
            dfs(nr, nc, path + dirNames[i], maze, n, visited, paths);
        }
    }
    visited[r][c] = false;
}

