function jobScheduling(jobs) {
  jobs.sort((a, b) => b.profit - a.profit);
  const maxDeadline = Math.max(...jobs.map(j => j.deadline));
  const slots = Array(maxDeadline + 1).fill(-1);
  let count = 0, profit = 0;
  for (let job of jobs) {
    for (let i = job.deadline; i > 0; i--) {
      if (slots[i] === -1) { slots[i] = job.id; count++; profit += job.profit; break; }
    }
  }
  return { count, profit };
}

