function closestPair(points) {
  points.sort((a, b) => a.x - b.x);
  function dist(p1, p2) {
    return Math.sqrt((p1.x - p2.x)**2 + (p1.y - p2.y)**2);
  }
  function solve(l, r) {
    if (r - l <= 3) {
      let minD = Infinity;
      for (let i = l; i <= r; i++) {
        for (let j = i + 1; j <= r; j++) minD = Math.min(minD, dist(points[i], points[j]));
      }
      return minD;
    }
    const mid = Math.floor((l + r) / 2);
    const midPt = points[mid];
    const dl = solve(l, mid), dr = solve(mid + 1, r);
    let d = Math.min(dl, dr);
    const strip = [];
    for (let i = l; i <= r; i++) {
      if (Math.abs(points[i].x - midPt.x) < d) strip.push(points[i]);
    }
    strip.sort((a, b) => a.y - b.y);
    for (let i = 0; i < strip.length; i++) {
      for (let j = i + 1; j < strip.length && (strip[j].y - strip[i].y) < d; j++) {
        d = Math.min(d, dist(strip[i], strip[j]));
      }
    }
    return d;
  }
  return solve(0, points.length - 1);
}

