    let i = l, j = mid + 1, k = 0, count = 0;
    const temp = [];
    while (i <= mid && j <= r) {
      if (arr[i] <= arr[j]) temp[k++] = arr[i++];
      else { temp[k++] = arr[j++]; count += (mid - i + 1); }
    }
    while (i <= mid) temp[k++] = arr[i++];
    while (j <= r) temp[k++] = arr[j++];
    for (i = l, k = 0; i <= r; i++, k++) arr[i] = temp[k];
    return count;
  }
  function solve(l, r) {
    if (l >= r) return 0;
    const mid = Math.floor((l + r) / 2);
    return solve(l, mid) + solve(mid + 1, r) + merge(l, mid, r);
  }
  return solve(0, arr.length - 1);
}

