        if memo[mask][u] != -1: return memo[mask][u]
        min_cost = float('inf')
        for v in range(n):
            if (mask & (1 << v)) == 0:
                cost = dist[u][v] + solve(mask | (1 << v), v)
                min_cost = min(min_cost, cost)
        memo[mask][u] = min_cost
        return min_cost
    return solve(1, 0)

