    int minCost = Integer.MAX_VALUE;
    for (int v = 0; v < n; v++) {
        if ((mask & (1 << v)) == 0) {
            int cost = dist[u][v] + solve(mask | (1 << v), v, n, dist, memo);
            minCost = Math.min(minCost, cost);
        }
    }
    return memo[mask][u] = minCost;
}

