int tsp(int n, vector<vector<int>>& dist) {
    vector<vector<int>> memo(1 << n, vector<int>(n, -1));
    auto solve = [&](auto self, int mask, int u) -> int {
        if (mask == (1 << n) - 1) return dist[u][0];
        if (memo[mask][u] != -1) return memo[mask][u];
        int minCost = 1e9;
        for (int v = 0; v < n; v++) {
            if ((mask & (1 << v)) == 0) {
                int cost = dist[u][v] + self(self, mask | (1 << v), v);
                minCost = min(minCost, cost);
            }
        }
        return memo[mask][u] = minCost;
    };
    return solve(solve, 1, 0);
}

