function intervalDP(arr) {
  const n = arr.length;
  const dp = Array.from({length: n}, () => Array(n).fill(0));
  for (let len = 1; len <= n; len++) {
    for (let i = 0; i <= n - len; i++) {
      const j = i + len - 1;
      if (i === j) { dp[i][j] = arr[i]; continue; }
      dp[i][j] = Infinity;
      for (let k = i; k < j; k++) {
        dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k + 1][j]);
      }
    }
  }
  return dp[0][n - 1];
}

